/* Calendar is a presentation of existing league days; simulation order is unchanged. */
let scheduleUI=null;
function scheduleDate(day){return new Date((state.scheduleFormat==='custom'?seasonDateRange(state.year,leagueRules()).start.getTime():Date.UTC(state.year,9,28))+(day-1)*86400000)}
function scheduleDateLabel(day,full=false){return scheduleDate(day).toLocaleDateString('en-US',{month:full?'long':'short',day:'numeric',...(full?{year:'numeric'}:{}),timeZone:'UTC'})}
function scheduleWeekday(day){return scheduleDate(day).toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})}
function scheduleWeekdayDateLabel(day){return scheduleWeekday(day)+', '+scheduleDateLabel(day)}
function scheduleMonth(day){return scheduleDate(day).toISOString().slice(0,7)}
function schedulePeriods(){return [...new Set(state.schedule.map((_,i)=>scheduleMonth(i+1)))]}
function scheduleSettings(){const key=activeSaveId+':'+state.year+':'+state.schedule.length;if(!scheduleUI||scheduleUI.key!==key){const day=Math.min(state.day+1,seasonLength());scheduleUI={key,competition:state.day>=seasonLength()?'playoffs':'regular',audience:leagueRules().scheduleAudience,scope:leagueRules().scheduleScope,month:scheduleMonth(day),week:Math.floor((day-1)/7)}}return scheduleUI}
function scheduleSelect(key,value){const ui=scheduleSettings();if(key==='competition'&&['regular','playoffs'].includes(value))ui.competition=value;if(key==='audience'&&['team','league'].includes(value))ui.audience=value;if(key==='scope'&&['season','month','week','remaining'].includes(value))ui.scope=value;if(key==='month'&&schedulePeriods().includes(value))ui.month=value;render()}
function scheduleNavigate(delta){const ui=scheduleSettings();if(ui.scope==='week')ui.week=Math.max(0,Math.min(Math.ceil(seasonLength()/7)-1,ui.week+delta));if(ui.scope==='week')ui.month=scheduleMonth(ui.week*7+1);else {const periods=schedulePeriods();ui.month=periods[Math.max(0,Math.min(periods.length-1,periods.indexOf(ui.month)+delta))]}render()}
function scheduleCurrent(){const ui=scheduleSettings(),day=Math.min(state.day+1,seasonLength());ui.month=scheduleMonth(day);ui.week=Math.floor((day-1)/7);if(!['month','week'].includes(ui.scope))ui.scope='month';render()}
function scheduleRows(){let number=0,w=0,l=0;return state.schedule.map((round,index)=>{const day=index+1,pair=round.find(pair=>pair.includes(controlledTeamId()));if(!pair)return {day,bye:true};const resultIndex=state.history.findIndex(g=>g.day===day&&g.stage==='Regular season'&&(g.a===controlledTeamId()||g.b===controlledTeamId())),result=state.history[resultIndex];if(result){if(result.winner===controlledTeamId())w++;else l++}const performers=result?.box.filter(p=>p.team===team().abbr&&p.played!==false&&Number.isFinite(p.pts)).sort((a,b)=>b.pts-a.pts||(b.reb||0)-(a.reb||0));return {day,number:++number,pair,opponent:state.teams[pair.find(id=>id!==controlledTeamId())],home:pair[0]===controlledTeamId(),result,resultIndex,record:result?w+'–'+l:'—',top:performers?.[0]}})}
function scheduleVisibleRows(rows){const ui=scheduleSettings();return rows.filter(r=>ui.scope==='season'||ui.scope==='remaining'&&r.day>state.day||ui.scope==='month'&&scheduleMonth(r.day)===ui.month||ui.scope==='week'&&Math.floor((r.day-1)/7)===ui.week)}
function scheduleSimulateThrough(day){if(!Number.isInteger(day)||day<=state.day||day>seasonLength())return;return sim(day-state.day)}
function scheduleSimulateNext(){const nextGame=(scheduleSettings().audience==='league'?leagueScheduleRows():scheduleRows()).find(r=>!r.bye&&r.day>state.day);if(nextGame)return scheduleSimulateThrough(nextGame.day)}
function scheduleMonthEnd(){const month=scheduleSettings().month;return state.schedule.reduce((last,_,i)=>scheduleMonth(i+1)===month?i+1:last,0)}
function scheduleMonthName(month){return new Date(month+'-01T00:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})}
function scheduleGameRow(row,nextDay){
 if(row.league)return leagueScheduleGameRow(row);
 if(row.bye)return `<div class="schedule-bye"><span>${scheduleWeekdayDateLabel(row.day)}</span><span>Rest day <small>· League day ${row.day}</small></span></div>`;
 const {result:r,opponent:opp,home,top}=row,won=r?.winner===controlledTeamId(),upNext=row.day===nextDay,score=r?(r.a===controlledTeamId()?r.sa:r.sb)+'–'+(r.a===controlledTeamId()?r.sb:r.sa):'—';
 return `<div class="schedule-game ${upNext?'schedule-next':''}"><span class="schedule-game-number" data-label="Game">${String(row.number).padStart(2,'0')}</span><div class="schedule-date" data-label="Date"><strong>${scheduleDateLabel(row.day)}</strong><small>${scheduleWeekday(row.day)} · Day ${row.day}</small></div><div class="schedule-opponent">${teamLogo(opp)}<div><strong><span class="muted">${home?'vs':'@'}</span> ${escapeHTML(opp.city+' '+opp.name)}</strong><small>${upNext?'NEXT GAME':escapeHTML(opp.conference||'')}${upNext?' · ':''}${upNext?escapeHTML(teamArena(home?team():opp)):''}</small></div></div><span class="schedule-venue" data-label="Venue" title="${home?'Home':'Away'}">${home?'H':'A'}</span><span data-label="Result" class="schedule-result ${r?(won?'schedule-win':'schedule-loss'):'schedule-pending'}">${r?(won?'W':'L'):'—'}</span><div class="schedule-score" data-label="Score">${r?`<button class="namebutton" onclick="showResult(${row.resultIndex})" aria-label="Box score for ${escapeHTML(opp.city)} on ${scheduleDateLabel(row.day)}">${score} ↗</button>`:score}</div><span class="schedule-record" data-label="Record">${row.record}</span><div class="schedule-performer" data-label="Top performer">${top?`<strong>${escapeHTML(top.name)}</strong><small>${top.pts} PTS · ${top.reb??'—'} REB · ${top.ast??'—'} AST</small>`:r?'—':row.day<=state.day?'Not recorded':`<button ${upNext?'class="primary"':''} onclick="scheduleSimulateThrough(${row.day})">${upNext?'Simulate game':'Sim to game'}</button>`}${scheduleSpread(row.pair[0],row.pair[1],row.result)}${scheduleMatchupButton(row.day,row.pair)}${watchGameButton(row.day,row.pair,row.result)}${scheduleInjuryField(row.day,row.pair,row.result)}</div></div>`;
}
function scheduleCompetitionToggle(){const ui=scheduleSettings();return `<nav class="po-tabs" aria-label="Schedule season type">${[['regular','Regular Season'],['playoffs','Playoffs']].map(([value,label])=>`<button aria-pressed="${ui.competition===value}" class="${ui.competition===value?'selected':''}" onclick="scheduleSelect('competition','${value}')">${label}</button>`).join('')}</nav>`}
scheduleView=function(){
 if(scheduleSettings().competition==='playoffs'){const ui=scheduleSettings();return `<div class="schedule-page">${scheduleCompetitionToggle()}<section class="panel"><div class="panelhead"><h2>Playoff Schedule &amp; Results</h2><span>${state.year}–${state.year+1}</span></div><div class="schedule-toolbar"><label>Teams<select aria-label="Schedule teams" onchange="scheduleSelect('audience',this.value)"><option value="team" ${ui.audience==='team'?'selected':''}>My team</option><option value="league" ${ui.audience==='league'?'selected':''}>Entire league</option></select></label></div>${state.day<seasonLength()?'<p class="note">Playoff matchups will be set when the regular season ends.</p>':''}</section>${state.day>=seasonLength()?postseasonSchedulePanel():''}</div>`}

 const ui=scheduleSettings(),rows=ui.audience==='league'?leagueScheduleRows():scheduleRows(),visible=scheduleVisibleRows(rows),nextGame=rows.find(r=>!r.bye&&r.day>state.day),periods=schedulePeriods(),week=ui.scope==='week',paged=week||ui.scope==='month',index=week?ui.week:periods.indexOf(ui.month),count=week?Math.ceil(seasonLength()/7):periods.length;
 const label=week?scheduleDateLabel(ui.week*7+1)+' – '+scheduleDateLabel(Math.min((ui.week+1)*7,seasonLength())):ui.scope==='season'?'Entire season':ui.scope==='remaining'?'Remaining games':scheduleMonthName(ui.month);
 const played=visible.filter(r=>r.result),wins=played.filter(r=>r.result.winner===controlledTeamId()).length,games=visible.filter(r=>!r.bye),monthEnd=scheduleMonthEnd(),postseason=state.history.map((g,index)=>({...g,index})).filter(g=>g.stage!=='Regular season'&&(g.a===controlledTeamId()||g.b===controlledTeamId()));
 return `<div class="schedule-page">${scheduleCompetitionToggle()}<section class="panel schedule-panel"><div class="schedule-title"><div><div class="eyebrow">${state.year}–${state.year+1} SEASON</div><h2>Schedule &amp; Results</h2><p>${ui.audience==='league'?'League-wide schedule':escapeHTML(team().city+' '+team().name)} <strong>${ui.audience==='league'?state.teams.length+' teams':team().w+'–'+team().l}</strong></p></div><div class="schedule-summary"><strong>${ui.audience==='league'?played.length+' finals':wins+'–'+(played.length-wins)}</strong><span>IN THIS VIEW</span><small>${games.length-played.length} games remaining</small></div></div><div class="schedule-toolbar"><label>Teams<select aria-label="Schedule teams" onchange="scheduleSelect('audience',this.value)"><option value="team" ${ui.audience!=='league'?'selected':''}>My team</option><option value="league" ${ui.audience==='league'?'selected':''}>Entire league</option></select></label><label>Show<select aria-label="Schedule view" onchange="scheduleSelect('scope',this.value)">${[['month','Month'],['week','Week'],['season','Entire season'],['remaining','Remaining games']].map(([value,text])=>`<option value="${value}" ${ui.scope===value?'selected':''}>${text}</option>`).join('')}</select></label>${ui.scope==='month'?`<label>Month<select aria-label="Schedule month" onchange="scheduleSelect('month',this.value)">${periods.map(month=>`<option value="${month}" ${month===ui.month?'selected':''}>${scheduleMonthName(month)}</option>`).join('')}</select></label>`:''}<div class="schedule-period"><button aria-label="Previous ${week?'week':'month'}" onclick="scheduleNavigate(-1)" ${!paged||index===0?'disabled':''}>‹</button><strong>${label}</strong><button aria-label="Next ${week?'week':'month'}" onclick="scheduleNavigate(1)" ${!paged||index===count-1?'disabled':''}>›</button></div><button onclick="scheduleCurrent()">Current ${week?'week':'month'}</button></div>${scheduleStrengthPanel()}${seasonCalendarBanner()}<div class="schedule-list"><div class="schedule-columns" style="${ui.audience==='league'?'display:none':''}" aria-hidden="true"><span>Game</span><span>Date</span><span>Opponent</span><span>H/A</span><span>Result</span><span>Score</span><span>Record</span><span>Top Performer</span></div>${scheduleRowsWithEvents(visible,nextGame?.day)||'<div class="schedule-empty">No games in this view.</div>'}</div><div class="schedule-footer"><div class="schedule-actions"><button class="primary" onclick="scheduleSimulateNext()" ${!nextGame?'disabled':''}>Simulate Next Game</button><button onclick="scheduleSimulateThrough(${monthEnd})" ${monthEnd<=state.day?'disabled':''}>Simulate ${scheduleMonthName(ui.month).split(' ')[0]}</button><button onclick="scheduleSimulateThrough(seasonLength())" ${state.day>=seasonLength()?'disabled':''}>Simulate to Playoffs</button><button onclick="sim(Math.min(7,seasonLength()-state.day))" ${state.day>=seasonLength()?'disabled':''}>Advance 7 days</button></div><p>${ui.audience==='league'?'League scores show the home team first.':'Scores show your team first.'} ${ui.audience==='league'?'Top performer is the game’s leading scorer.':'Top performer is your team’s leading scorer.'} Fast-forward plays all intervening league games.</p><p>${state.scheduleFormat==='custom'?leagueRules().seasonGames+' games per team · '+leagueRules().divisionGames+' division · '+leagueRules().conferenceGames+' other conference · '+(leagueRules().seasonGames-leagueRules().divisionGames-leagueRules().conferenceGames)+' interconference.':state.scheduleFormat==='nba82'?'82 games · 41 home / 41 away · Maximum 16 back-to-backs · No three consecutive game nights.':state.scheduleFormat!=='roundRobin'&&nbaAlignment(state.teams)?'Your current schedule is preserved. The next season will use the 82-game format.':'Custom league · Balanced round-robin schedule.'}</p><p>${state.schedule.flat().length.toLocaleString()} league games · ${seasonLength()} calendar days · ${(state.schedule.flat().length/seasonLength()).toFixed(1)} games per day on average.</p><p>Calendar starts ${scheduleDateLabel(1,true)}; each league day advances one calendar day. Regular-season record shown after each game.</p></div></section></div>`;
};

// Each scheduled matchup contributes once; repeat opponents carry repeat weight.
function scheduleStrengthRows(){
 const days=new Set(scheduleVisibleRows(state.schedule.map((_,i)=>({day:i+1}))).map(r=>r.day));
 const results=state.history.filter(g=>g.stage==='Regular season'),projected=results.length===0;
 const rows=state.teams.map(club=>{
  const opponents=state.schedule.flatMap((round,i)=>days.has(i+1)?round.filter(pair=>pair.includes(club.id)).map(pair=>pair.find(id=>id!==club.id)):[]);
  const score=opponents.length?opponents.reduce((sum,id)=>{if(projected)return sum+strength(state.teams[id]);const games=results.filter(g=>(g.a===id||g.b===id)&&g.a!==club.id&&g.b!==club.id);return sum+(games.length?games.filter(g=>g.winner===id).length/games.length:.5)},0)/opponents.length:null;
  return {club,games:opponents.length,score:score===null?null:Math.round(score*1e6)/1e6,projected};
 });
 const ranked=rows.filter(r=>r.score!==null).sort((a,b)=>b.score-a.score||a.club.id-b.club.id),low=ranked.at(-1)?.score,high=ranked[0]?.score;
 for(const row of ranked){row.rank=1+ranked.filter(r=>r.score>row.score).length;row.tied=ranked.filter(r=>r.score===row.score).length>1;const percentile=ranked.length>1?(row.rank-1)/(ranked.length-1):.5;row.tier=high===low?'balanced':row.score===high?'hard':row.score===low?'easy':percentile<1/3?'hard':percentile>=2/3?'easy':'balanced';row.label={hard:'Harder',easy:'Easier',balanced:'Balanced'}[row.tier]}
 return ranked;
}
function scheduleStrengthPanel(){
 const rows=scheduleStrengthRows(),own=rows.find(r=>r.club.id===controlledTeamId()),projected=rows[0]?.projected,league=scheduleSettings().audience==='league';
 const score=r=>r.projected?r.score.toFixed(1)+' OVR':(r.score*100).toFixed(1)+'%';
 const badge=r=>`<span class="sos-badge sos-${r.tier}">${r.tied?'T-':'#'}${r.rank} / ${rows.length} · ${r.label}</span>`;
 return `<section class="schedule-sos" aria-label="Strength of schedule"><div class="sos-heading"><div><h3>Strength of schedule</h3><small>${projected?'Preseason projection · Opponent team ratings':'Opponent winning percentage · Excludes games against the evaluated team'}</small></div>${own?`<div class="sos-summary">${badge(own)}<strong>${score(own)}</strong><small>${own.games} matchups · ${escapeHTML(team().abbr)}</small></div>`:'<span class="muted">No team games in this view</span>'}</div><details ${league?'open':''}><summary>League difficulty rankings <span class="sos-hard">Red: hardest</span> · <span class="sos-easy">Green: easiest</span></summary><div class="scroll"><table><thead><tr><th>Difficulty rank</th><th>Team</th><th>Games</th><th>${projected?'Avg opponent OVR':'Opponent win%'}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${badge(r)}</td><td><span class="sos-team">${secondaryTeamLogo(r.club)}<span>${escapeHTML(r.club.city+' '+r.club.name)}</span></span></td><td>${r.games}</td><td>${score(r)}</td></tr>`).join('')||'<tr><td colspan="4">No scheduled games in this view.</td></tr>'}</tbody></table></div></details><p>Ranks follow the selected month, week, entire season, or remaining-games view. #1 is hardest. Repeat opponents count once per matchup. ${projected?'Projections use current roster ratings until regular-season results are available.':'An opponent with no qualifying games counts as .500. Rankings update as league results change.'}</p></section>`;
}
